int verify_replay_state_length(struct xfrm_replay_state_esn *replay_esn, struct nlattr *rp) {
    int len = nla_len(rp);

    if (!replay_esn || !rp) {
        return -EINVAL;
    }

    if (len < sizeof(*replay_esn)) {
        return -EINVAL;
    }

    if (replay_esn->replay_window > len * 8) {
        return -EINVAL;
    }

    return 0;
}
